import{_ as e,o as t,c as r,ag as o}from"./chunks/framework.DTisvaUJ.js";const c=JSON.parse('{"title":"자주 묻는 질문 — 설치·음성 인식·읽기","description":"설치·업데이트·인식·읽기·번역·VR 조작·무료 및 유료 기능에 관한 질문입니다.","frontmatter":{"title":"자주 묻는 질문 — 설치·음성 인식·읽기","description":"설치·업데이트·인식·읽기·번역·VR 조작·무료 및 유료 기능에 관한 질문입니다.","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/ko/help/faq"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:title","content":"자주 묻는 질문 — 설치·음성 인식·읽기 | Mutelink"}],["meta",{"property":"og:description","content":"설치·업데이트·인식·읽기·번역·VR 조작·무료 및 유료 기능에 관한 질문입니다."}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/ko/help/faq"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"property":"og:image:width","content":"1920"}],["meta",{"property":"og:image:height","content":"1080"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"자주 묻는 질문 — 설치·음성 인식·읽기 | Mutelink"}],["meta",{"name":"twitter:description","content":"설치·업데이트·인식·읽기·번역·VR 조작·무료 및 유료 기능에 관한 질문입니다."}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/help/faq"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/help/faq"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/help/faq"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/help/faq"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/help/faq"}]]},"headers":[],"relativePath":"ko/help/faq.md","filePath":"ko/help/faq.md"}'),i={name:"ko/help/faq.md"};function n(l,a,h,s,u,p){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="q-a" tabindex="-1">Q&amp;A <a class="header-anchor" href="#q-a" aria-label="Permalink to &quot;Q&amp;A {#q-a}&quot;">​</a></h1><p>자주 묻는 질문입니다. 문제가 있다면 <a href="/Mutelink-releases/ko/help/troubleshooting">문제 해결</a>을 참고하세요.</p><h2 id="インストール・更新" tabindex="-1">설치·업데이트 <a class="header-anchor" href="#インストール・更新" aria-label="Permalink to &quot;설치·업데이트 {#インストール・更新}&quot;">​</a></h2><h3 id="「windowsによってpcが保護されました」と出ます" tabindex="-1">Windows의 PC 보호 메시지가 나옵니다 <a class="header-anchor" href="#「windowsによってpcが保護されました」と出ます" aria-label="Permalink to &quot;Windows의 PC 보호 메시지가 나옵니다 {#「windowsによってpcが保護されました」と出ます}&quot;">​</a></h3><p>코드 서명이 없어 표시될 수 있습니다. 추가 정보 후 실행을 누르세요. 관리자 권한은 필요 없습니다.</p><h3 id="新しいバージョンが出たことは、どうやって分かりますか" tabindex="-1">새 버전은 어떻게 알 수 있나요? <a class="header-anchor" href="#新しいバージョンが出たことは、どうやって分かりますか" aria-label="Permalink to &quot;새 버전은 어떻게 알 수 있나요? {#新しいバージョンが出たことは、どうやって分かりますか}&quot;">​</a></h3><p>시작 시 앱 안에서 알립니다. 설정 &gt; 기타 &gt; 앱 정보에서도 확인할 수 있습니다.</p><h3 id="設定の説明は、どこにありますか" tabindex="-1">설정 설명은 어디 있나요? <a class="header-anchor" href="#設定の説明は、どこにありますか" aria-label="Permalink to &quot;설정 설명은 어디 있나요? {#設定の説明は、どこにありますか}&quot;">​</a></h3><p>설정 오른쪽 위 “?”를 누르면 각 항목 옆에 설명이 나옵니다. 사이트에는 모든 설정을 나열하지 않습니다.</p><h3 id="設定の項目が、少なく見えます" tabindex="-1">설정 항목이 적게 보입니다 <a class="header-anchor" href="#設定の項目が、少なく見えます" aria-label="Permalink to &quot;설정 항목이 적게 보입니다 {#設定の項目が、少なく見えます}&quot;">​</a></h3><p>설정 &gt; 사용 방식에서 고른 용도에 맞는 항목만 표시합니다. 같은 페이지의 모두 표시를 고르면 전체가 나옵니다.</p><h2 id="音声認識" tabindex="-1">음성 인식 <a class="header-anchor" href="#音声認識" aria-label="Permalink to &quot;음성 인식 {#音声認識}&quot;">​</a></h2><h3 id="音声認識のエンジンは、どれを選べばいいですか" tabindex="-1">어떤 인식 엔진을 고르면 되나요? <a class="header-anchor" href="#音声認識のエンジンは、どれを選べばいいですか" aria-label="Permalink to &quot;어떤 인식 엔진을 고르면 되나요? {#音声認識のエンジンは、どれを選べばいいですか}&quot;">​</a></h3><p>일본어는 Parakeet 일본어 TDT 또는 Haas-ja, 영어는 Parakeet 영어, 나머지는 Qwen3-ASR 또는 Whisper turbo를 권장합니다. <a href="/Mutelink-releases/ko/compare/speech-recognition">엔진 비교</a>를 보세요.</p><h3 id="声を、pcの外に出したくありません" tabindex="-1">음성을 PC 밖으로 보내고 싶지 않습니다 <a class="header-anchor" href="#声を、pcの外に出したくありません" aria-label="Permalink to &quot;음성을 PC 밖으로 보내고 싶지 않습니다 {#声を、pcの外に出したくありません}&quot;">​</a></h3><p>로컬 Parakeet·Haas-ja·Qwen3-ASR·Whisper turbo는 음성을 외부로 보내지 않습니다. 클라우드는 Microsoft 또는 Google로 보냅니다(<a href="/Mutelink-releases/ko/about/privacy">개인정보</a>).</p><h3 id="友達の名前が、正しく認識されません" tabindex="-1">친구 이름이 잘 인식되지 않습니다 <a class="header-anchor" href="#友達の名前が、正しく認識されません" aria-label="Permalink to &quot;친구 이름이 잘 인식되지 않습니다 {#友達の名前が、正しく認識されません}&quot;">​</a></h3><p>Parakeet 일본어 TDT는 설정 &gt; 말하기 &gt; 언어와 인식의 단어와 이름에 등록하면 해당 단어가 더 잘 나옵니다.</p><h3 id="言語の「自動」が選べません" tabindex="-1">언어 자동을 선택할 수 없습니다 <a class="header-anchor" href="#言語の「自動」が選べません" aria-label="Permalink to &quot;언어 자동을 선택할 수 없습니다 {#言語の「自動」が選べません}&quot;">​</a></h3><p>자동은 Qwen3-ASR와 Whisper turbo만 지원합니다.</p><h2 id="読み上げの声" tabindex="-1">읽기 목소리 <a class="header-anchor" href="#読み上げの声" aria-label="Permalink to &quot;읽기 목소리 {#読み上げの声}&quot;">​</a></h2><h3 id="どの声を選べばいいですか" tabindex="-1">어떤 목소리를 고르면 되나요? <a class="header-anchor" href="#どの声を選べばいいですか" aria-label="Permalink to &quot;어떤 목소리를 고르면 되나요? {#どの声を選べばいいですか}&quot;">​</a></h3><p>GPU 없이 캐릭터 목소리는 VOICEVOX, 빠르고 자연스러운 일본어는 Irodori-TTS, 다른 언어는 Qwen3-TTS를 고르세요. <a href="/Mutelink-releases/ko/compare/voices">목소리 비교</a>에서 들어 보세요.</p><h3 id="gpuは必要ですか" tabindex="-1">GPU가 필요한가요? <a class="header-anchor" href="#gpuは必要ですか" aria-label="Permalink to &quot;GPU가 필요한가요? {#gpuは必要ですか}&quot;">​</a></h3><p>VOICEVOX와 채팅창 전송만은 GPU가 필요 없습니다. Irodori-TTS·Qwen3-TTS는 Vulkan 지원 GPU가 필요합니다.</p><h3 id="自分の声に似せた声で、読み上げられますか" tabindex="-1">제 목소리처럼 읽을 수 있나요? <a class="header-anchor" href="#自分の声に似せた声で、読み上げられますか" aria-label="Permalink to &quot;제 목소리처럼 읽을 수 있나요? {#自分の声に似せた声で、読み上げられますか}&quot;">​</a></h3><p>Irodori-TTS·Qwen3-TTS에서 녹음을 등록할 수 있습니다(<a href="/Mutelink-releases/ko/about/supporter">후원판</a>). 본인 목소리 또는 명확히 동의받은 목소리만 사용하세요.</p><h3 id="日本語以外も、読み上げられますか" tabindex="-1">일본어 외 언어도 읽나요? <a class="header-anchor" href="#日本語以外も、読み上げられますか" aria-label="Permalink to &quot;일본어 외 언어도 읽나요? {#日本語以外も、読み上げられますか}&quot;">​</a></h3><p>Qwen3-TTS는 영어·중국어·한국어·독일어·스페인어·프랑스어·이탈리아어·포르투갈어·러시아어를 읽습니다.</p><h2 id="翻訳" tabindex="-1">번역 <a class="header-anchor" href="#翻訳" aria-label="Permalink to &quot;번역 {#翻訳}&quot;">​</a></h2><h3 id="翻訳は無料ですか" tabindex="-1">번역은 무료인가요? <a class="header-anchor" href="#翻訳は無料ですか" aria-label="Permalink to &quot;번역은 무료인가요? {#翻訳は無料ですか}&quot;">​</a></h3><p>번역·번역문 채팅창 전송·들리는 음성 번역은 무료입니다. 번역문 읽기만 <a href="/Mutelink-releases/ko/about/supporter">후원판</a>이 필요합니다.</p><h3 id="どの翻訳エンジンがいいですか" tabindex="-1">어떤 번역 엔진이 좋은가요? <a class="header-anchor" href="#どの翻訳エンジンがいいですか" aria-label="Permalink to &quot;어떤 번역 엔진이 좋은가요? {#どの翻訳エンジンがいいですか}&quot;">​</a></h3><p>언어에 따라 다릅니다. <a href="/Mutelink-releases/ko/compare/translation">번역 비교</a>의 실제 출력을 보고 고르세요. 글을 PC 밖으로 보내지 않으려면 PLaMo 또는 TranslateGemma를 선택하세요.</p><h3 id="訳した文を、確認してから送れますか" tabindex="-1">번역을 확인한 뒤 보낼 수 있나요? <a class="header-anchor" href="#訳した文を、確認してから送れますか" aria-label="Permalink to &quot;번역을 확인한 뒤 보낼 수 있나요? {#訳した文を、確認してから送れますか}&quot;">​</a></h3><p>아니요. 전송 직전에 번역하여 그대로 보냅니다.</p><h2 id="聞こえた声" tabindex="-1">들리는 음성 <a class="header-anchor" href="#聞こえた声" aria-label="Permalink to &quot;들리는 음성 {#聞こえた声}&quot;">​</a></h2><h3 id="聞こえた声とは何ですか" tabindex="-1">들리는 음성이란 무엇인가요? <a class="header-anchor" href="#聞こえた声とは何ですか" aria-label="Permalink to &quot;들리는 음성이란 무엇인가요? {#聞こえた声とは何ですか}&quot;">​</a></h3><p>VRChat 소리를 인식해 상대의 말을 글로 보여 주는 기능이며 번역도 표시할 수 있습니다.</p><h3 id="聞こえた声は、相手に見えますか" tabindex="-1">상대도 이 글을 볼 수 있나요? <a class="header-anchor" href="#聞こえた声は、相手に見えますか" aria-label="Permalink to &quot;상대도 이 글을 볼 수 있나요? {#聞こえた声は、相手に見えますか}&quot;">​</a></h3><p>메인 목록과 VR 패널은 본인에게만 보입니다. 채팅창 출력을 켜면(기본 꺼짐) 인스턴스의 모두에게 보입니다.</p><h2 id="vr" tabindex="-1">VR <a class="header-anchor" href="#vr" aria-label="Permalink to &quot;VR {#vr}&quot;">​</a></h2><h3 id="steamvrは必須ですか" tabindex="-1">SteamVR가 꼭 필요한가요? <a class="header-anchor" href="#steamvrは必須ですか" aria-label="Permalink to &quot;SteamVR가 꼭 필요한가요? {#steamvrは必須ですか}&quot;">​</a></h3><p>아니요. SteamVR 없이 데스크톱에서 사용하고 단축키로 전송·언어 전환도 할 수 있습니다(설정 &gt; 기타 &gt; 단축키).</p><h3 id="steamvrと一緒に、起動できますか" tabindex="-1">SteamVR와 함께 시작할 수 있나요? <a class="header-anchor" href="#steamvrと一緒に、起動できますか" aria-label="Permalink to &quot;SteamVR와 함께 시작할 수 있나요? {#steamvrと一緒に、起動できますか}&quot;">​</a></h3><p>설정 &gt; 외관 &gt; VR에서 SteamVR와 함께 시작·종료를 켜세요. 연결할 때 등록하므로 최초 한 번은 SteamVR가 실행된 상태에서 Mutelink를 시작하세요.</p><h2 id="支援版・データ" tabindex="-1">후원판·데이터 <a class="header-anchor" href="#支援版・データ" aria-label="Permalink to &quot;후원판·데이터 {#支援版・データ}&quot;">​</a></h2><h3 id="支援版を買わないと、使えませんか" tabindex="-1">후원판을 꼭 사야 하나요? <a class="header-anchor" href="#支援版を買わないと、使えませんか" aria-label="Permalink to &quot;후원판을 꼭 사야 하나요? {#支援版を買わないと、使えませんか}&quot;">​</a></h3><p>아니요. 앱은 무료이며 구매 없이 쓸 수 있습니다. 차이는 <a href="/Mutelink-releases/ko/about/supporter">후원판</a>을 보세요.</p><h3 id="どんなデータが、外に送られますか" tabindex="-1">어떤 데이터를 외부로 보내나요? <a class="header-anchor" href="#どんなデータが、外に送られますか" aria-label="Permalink to &quot;어떤 데이터를 외부로 보내나요? {#どんなデータが、外に送られますか}&quot;">​</a></h3><p><a href="/Mutelink-releases/ko/about/privacy">개인정보</a>를 참고하세요.</p>',51)])])}const m=e(i,[["render",n]]);export{c as __pageData,m as default};
